component.css:
.cyber-beta-container * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }
  .cyber-beta-container {
    font-family: 'Courier New', monospace;
    max-width: 400px;
    width: 100%;
    margin: 0 auto;
    padding: 4px 0;
  }
  .cyber-panel-beta {
    background: #0a0e1a;
    border: 2px solid #ffcc00;
    border-radius: 14px;
    padding: 20px 22px 22px 22px;
    box-shadow: 0 0 30px rgba(255, 204, 0, 0.12), inset 0 0 40px rgba(255, 204, 0, 0.03);
  }
  .cyber-header-beta {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
  }
  .cyber-icon-beta {
    font-size: 24px;
    color: #ffcc00;
    text-shadow: 0 0 12px #ffcc0088;
  }
  .cyber-title-beta {
    font-size: 20px;
    font-weight: 700;
    letter-spacing: 2px;
    color: #ffecb0;
    text-shadow: 0 0 10px #ffcc0055;
    flex: 1;
  }
  .cyber-badge-beta {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.5px;
    padding: 4px 12px;
    border-radius: 30px;
    background: #ffcc0022;
    border: 1px solid #ffcc00aa;
    color: #ffcc00;
    text-shadow: 0 0 6px #ffcc0066;
  }
  .cyber-badge-warn-beta {
    border-color: #ff8800aa;
    color: #ff8800;
    background: #ff880022;
  }
  .cyber-divider-beta {
    height: 2px;
    background: linear-gradient(90deg, transparent, #ffcc0077, transparent);
    margin: 14px 0 16px 0;
    border: none;
  }
  .cyber-body-beta {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .cyber-text-beta {
    font-size: 14px;
    line-height: 1.7;
    color: #ccbb88;
    letter-spacing: 0.3px;
  }
  .cyber-status-beta {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 13px;
    color: #aa9944;
  }
  .cyber-dot-beta {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: #ffcc00;
    box-shadow: 0 0 16px #ffcc00aa;
    animation: cyber-pulse-beta 1.6s ease-in-out infinite;
  }
  .cyber-dot-warn-beta {
    background: #ff8800;
    box-shadow: 0 0 16px #ff880088;
  }
  @keyframes cyber-pulse-beta {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.3; transform: scale(0.8); }
  }
  .cyber-highlight-beta {
    color: #ffcc00;
    font-weight: 600;
    text-shadow: 0 0 8px #ffcc0066;
  }
  .cyber-footer-beta {
    margin-top: 18px;
    display: flex;
    justify-content: flex-end;
  }
  .cyber-btn-beta {
    font-family: 'Courier New', monospace;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.8px;
    padding: 10px 24px;
    border-radius: 30px;
    border: none;
    cursor: pointer;
    transition: all 0.25s ease;
    text-transform: uppercase;
    background: transparent;
  }
  .cyber-btn-secondary-beta {
    background: #ffcc0022;
    border: 1.5px solid #ffcc00;
    color: #ffcc00;
    box-shadow: 0 0 16px transparent;
  }
  .cyber-btn-secondary-beta:hover {
    background: #ffcc0044;
    box-shadow: 0 0 32px #ffcc0044;
    transform: scale(1.03);
  }
  .cyber-btn-beta:active {
    transform: scale(0.95);
  }

component.script:
(function() {
    var raw = getMsgContent() || '';
    var d = String.fromCharCode(36);

    function extract(tag) {
      var reg = new RegExp('<' + tag + '>([\\s\\S]*?)</' + tag + '>', 'i');
      var m = raw.match(reg);
      return m ? m[1].trim() : '';
    }

    var title = extract('title') || 'Beta 终端';
    var subText = extract('subText') || '备用链路待命 · 等待激活指令';

    setText('#betaTitle', title);
    setText('#betaSubText', subText);

    document.getElementById('betaSwitchBtn').addEventListener('click', function() {
      var currentTitle = extract('title') || 'Beta 终端';
      var currentSubText = extract('subText') || '备用链路待命 · 等待激活指令';
      changeMsg(
        '<' + d + 'CyberPanelAlpha' + d + '>' +
        '<title>' + currentTitle + '</title>' +
        '<subText>' + currentSubText + '</subText>' +
        '</' + d + 'CyberPanelAlpha' + d + '>'
      );
    });
  })();
